  const mounted = useMounted()
  const lastSolidMenuAccentRef = React.useRef(params.menuAccent)
  const isDark = mounted && resolvedTheme === "dark"
  const currentMenu = MENU_OPTIONS.find(
    (menu) => menu.value === params.menuColor
