    // via a postMessage channel, for it to sync its own history onto the host's.
    return serializeDesignSystemSearchParams(
      `/preview/${params.base}/${params.item}`,
      params
    )
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [params.base, params.item])

  return (
    <div className="relative flex flex-1 flex-col justify-center overflow-hidden rounded-2xl ring ring-foreground/10 md:ring-muted dark:ring-foreground/10">
      <div className="relative z-0 mx-auto flex w-full flex-1 flex-col overflow-hidden">
        <div className="absolute inset-0 bg-muted dark:bg-muted/30" />
        <iframe
          key={params.base + params.item}
          ref={iframeRef}
          src={iframeSrc}
          className="z-10 size-full flex-1"
          title="Preview"
        />
      </div>
      <CreateDevtools />
      <PreviewSwitcher />
    </div>
  )
}
"use client"

import * as React from "react"

import { BASES } from "@/registry/config"
import { Button } from "@/registry/new-york-v4/ui/button"
import { getDocsPathForItem } from "@/app/(app)/(create)/lib/devtools"
import {
  serializeDesignSystemSearchParams,
  useDesignSystemSearchParams,
} from "@/app/(app)/(create)/lib/search-params"

export function CreateDevtools() {
  const [params, setParams] = useDesignSystemSearchParams()

  const previewUrl = React.useMemo(
    () =>
      serializeDesignSystemSearchParams(
        `/preview/${params.base}/${params.item}`,
        params
      ),
    [params]
  )

  const docsUrl = React.useMemo(
    () => getDocsPathForItem(params.base, params.item),
    [params.base, params.item]
  )

  if (process.env.NODE_ENV === "production") {
    return null
  }

  return (
    <div className="dark absolute bottom-3 left-1/2 z-20 flex -translate-x-1/2 items-center gap-0.5 rounded-xl bg-card/90 p-1 shadow-xl backdrop-blur-xl">
      {BASES.map((base) => (
        <Button
          key={base.name}
          variant="ghost"
          size="sm"
          data-active={params.base === base.name}
          className="h-7 min-w-8 cursor-pointer rounded-lg px-2.5 text-xs font-medium text-muted-foreground transition-colors hover:text-foreground data-[active=true]:bg-accent data-[active=true]:text-accent-foreground"
          onClick={() => setParams({ base: base.name })}
        >
          {base.title}
        </Button>
      ))}
      <div className="mx-0.5 h-4 w-px bg-border/80" />
      <Button
        asChild
        variant="ghost"
        size="sm"
        className="h-7 rounded-lg px-2.5 text-xs font-medium text-muted-foreground hover:text-foreground"
      >
        <a href={previewUrl} target="_blank" rel="noreferrer">
          Open in New Tab
        </a>
      </Button>
      <div className="mx-0.5 h-4 w-px bg-border/80" />
      <Button
        asChild
        variant="ghost"
        size="sm"
        className="h-7 rounded-lg px-2.5 text-xs font-medium text-muted-foreground hover:text-foreground"
      >
        <a href={docsUrl} target="_blank" rel="noreferrer">
          Open Docs
        </a>
      </Button>
    </div>
  )
}
import { type BaseName } from "@/registry/config"

export function getDocsPathForItem(base: BaseName, item: string) {
  if (item.endsWith("-example")) {
    const component = item.slice(0, -"-example".length)
    return `/docs/components/${base}/${component}`
  }

  return "/docs/components"
}
"use client"

import { Button } from "@/registry/new-york-v4/ui/button"
import { useDesignSystemSearchParams } from "@/app/(app)/(create)/lib/search-params"

const PREVIEW_ITEMS = [
  { label: "01", value: "preview-02" },
  { label: "02", value: "preview" },
]

export function PreviewSwitcher() {
  const [params, setParams] = useDesignSystemSearchParams()

  const isPreview =
    params.item === "preview" || params.item.startsWith("preview-0")

  if (!isPreview) {
    return null
  }

  return (
    <div className="dark absolute right-3 bottom-3 z-20 flex items-center gap-1 rounded-xl bg-card/90 p-1 shadow-xl backdrop-blur-xl">
      {PREVIEW_ITEMS.map((item) => (
        <Button
          key={item.value}
          variant="ghost"
          size="sm"
          data-active={params.item === item.value}
          className="h-7 min-w-8 cursor-pointer rounded-lg px-2.5 text-xs font-medium text-muted-foreground transition-colors hover:text-foreground data-[active=true]:bg-accent data-[active=true]:text-accent-foreground"
          onClick={() => setParams({ item: item.value })}
        >
          {item.label}
        </Button>
      ))}
    </div>
  )
}
